test("day 31 uses month end when missing and the next month returns to 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 3 }), ["2026-02-28", "2026-03-31", "2026-04-30"]);
});

test("December 31 rolls into January and leap February ends on the 29th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2027-12-31", count: 3 }), ["2028-01-31", "2028-02-29", "2028-03-31"]);
});

test("day 15 exists every month so dates stay on the 15th", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-15", count: 2 }), ["2026-02-15", "2026-03-15"]);
});

test("one payment is due one month after the start", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-06-15", count: 1 }), ["2026-07-15"]);
});

test("the second date restores 31 after a shortened February", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 2 }), ["2026-02-28", "2026-03-31"]);
});

test("the 1st exists in every following month", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-01", count: 3 }), ["2026-02-01", "2026-03-01", "2026-04-01"]);
});

test("December 1 crosses into January and February of the next year", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-12-01", count: 3 }), ["2027-01-01", "2027-02-01", "2027-03-01"]);
});

test("a shortened February sits after a December 31 year boundary", function () {
  assert.deepEqual(code.dueDates({ startDate: "2025-12-31", count: 3 }), ["2026-01-31", "2026-02-28", "2026-03-31"]);
});

test("day 30 clamps only in February and the next month returns to 30", function () {
  assert.deepEqual(code.dueDates({ startDate: "2025-11-30", count: 4 }), ["2025-12-30", "2026-01-30", "2026-02-28", "2026-03-30"]);
});

test("the only returned date is a shortened February 28", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-31", count: 1 }), ["2026-02-28"]);
});

test("day 28 is kept on non-leap February and March stays 28", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-28", count: 2 }), ["2026-02-28", "2026-03-28"]);
});

test("day 29 clamps in non-leap February then returns to 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-01-29", count: 3 }), ["2026-02-28", "2026-03-29", "2026-04-29"]);
});

test("day 29 is kept on leap day and March stays 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-29", count: 2 }), ["2028-02-29", "2028-03-29"]);
});

test("day 30 clamps to leap February 29 and March returns to 30", function () {
  assert.deepEqual(code.dueDates({ startDate: "2028-01-30", count: 2 }), ["2028-02-29", "2028-03-30"]);
});

test("June clamps the 31st to 30 and later months return to 31", function () {
  assert.deepEqual(code.dueDates({ startDate: "2026-05-31", count: 3 }), ["2026-06-30", "2026-07-31", "2026-08-31"]);
});

test("a leap-day start clamps only the next non-leap February then returns to 29", function () {
  assert.deepEqual(code.dueDates({ startDate: "2024-02-29", count: 13 }), ["2024-03-29", "2024-04-29", "2024-05-29", "2024-06-29", "2024-07-29", "2024-08-29", "2024-09-29", "2024-10-29", "2024-11-29", "2024-12-29", "2025-01-29", "2025-02-28", "2025-03-29"]);
});
